import 'commands.dart';
import 'model/card.dart';
import 'model/game_state.dart';

/// Why a turn started — lets the UI pick an animation.
enum TurnStartReason {
  gameStart,
  normal,
  detonate,
  steal,
  nopeRevert,
  ghostSkip,
}

enum DrawReason { reward, penalty, stolen }

/// Something that happened. Events are derived output: the replay stores
/// commands, and events are regenerated by the engine.
sealed class GameEvent {
  const GameEvent(this.ts);

  final int ts;

  String get type;

  Map<String, Object?> _fields();

  Map<String, Object?> toJson() => {'type': type, 'ts': ts, ..._fields()};

  @override
  String toString() {
    final f = _fields().entries.map((e) => '${e.key}=${e.value}').join(' ');
    return '[$ts] $type $f';
  }
}

final class GameStarted extends GameEvent {
  const GameStarted(super.ts, {required this.playerIds, required this.target});
  final List<String> playerIds;
  final Card target;
  @override
  String get type => 'gameStarted';
  @override
  Map<String, Object?> _fields() => {
    'players': playerIds,
    'target': target.toJson(),
  };
}

final class TurnStarted extends GameEvent {
  const TurnStarted(
    super.ts, {
    required this.playerId,
    required this.seq,
    required this.round,
    required this.limitMs,
    required this.reason,
  });
  final String playerId;
  final int seq;
  final int round;
  final int limitMs;
  final TurnStartReason reason;
  @override
  String get type => 'turnStarted';
  @override
  Map<String, Object?> _fields() => {
    'playerId': playerId,
    'seq': seq,
    'round': round,
    'limitMs': limitMs,
    'reason': reason.name,
  };
}

final class TurnLimitChanged extends GameEvent {
