/// A valid throw onto the deck.
final class CardThrown extends GameEvent {
  const CardThrown(
    super.ts, {
    required this.playerId,
    required this.card,
    required this.throwMs,
    required this.draw,
    this.targetPlayerId,
  });
  final String playerId;
  final Card card;

  /// Time from turn start to the throw.
  final int throwMs;

  /// Cards drawn as the time-based reward.
  final int draw;
  final String? targetPlayerId;
  @override
  String get type => 'cardThrown';
  @override
  Map<String, Object?> _fields() => {
    'playerId': playerId,
    'card': card.toJson(),
    'throwMs': throwMs,
    'draw': draw,
    if (targetPlayerId != null) 'target': targetPlayerId,
  };
}

